    return version if isinstance(version, Version) else parse(version)


def _cmp(a, b) -> int:
    return (a > b) - (a < b)


def _compare_identifiers(a: str, b: str) -> int:
    a_numeric = _DIGITS_RE.fullmatch(a) is not None
    b_numeric = _DIGITS_RE.fullmatch(b) is not None
    if a_numeric and b_numeric:
        return _cmp(int(a), int(b))
    if a_numeric != b_numeric:
        return -1 if a_numeric else 1
    return _cmp(a, b)


