    """Return -1, 0, or 1 as ``a`` has lower, equal, or higher precedence."""
    a, b = _coerce(a), _coerce(b)
    result = _cmp((a.major, a.minor, a.patch), (b.major, b.minor, b.patch))
    if result:
        return result
    if not a.prerelease or not b.prerelease:
        # Whichever has no pre-release (if either) is higher.
        return _cmp(not a.prerelease, not b.prerelease)
    for x, y in zip(a.prerelease, b.prerelease):
        result = _compare_identifiers(x, y)
        if result:
            return result
    return _cmp(len(a.prerelease), len(b.prerelease))


