    """The exclusive upper bound of ``^v`` or ``~v``."""
    if op == "^" and v.major:
        return Version(v.major + 1, 0, 0)
    if op == "~" or v.minor:
        return Version(v.major, v.minor + 1, 0)
    return Version(v.major, v.minor, v.patch + 1)


def _holds(version: Version, op: str, bound: Version) -> bool:
    result = compare(version, bound)
    if op == "=":
        return result == 0
    if op == ">":
        return result > 0
    if op == ">=":
        return result >= 0
    if op == "<":
        return result < 0
    if op == "<=":
        return result <= 0
    return result >= 0 and compare(version, _upper_bound(op, bound)) < 0


def satisfies(version: str | Version, range_: str) -> bool:
    """Whether ``version`` is in ``range_``."""
    version = _coerce(version)
    sets = []
    for part in range_.split("||"):
        comparators = [_parse_comparator(c) for c in part.split()]
        if not comparators:
            raise ValueError(f"invalid range: {range_!r}")
        sets.append(comparators)
    core = (version.major, version.minor, version.patch)
    for comparators in sets:
        if not all(_holds(version, op, bound) for op, bound in comparators):
            continue
        if not version.prerelease or any(
            bound.prerelease and (bound.major, bound.minor, bound.patch) == core
            for _, bound in comparators
        ):
            return True
    return False

