from __future__ import annotations

import calendar
import re
from dataclasses import dataclass
from datetime import datetime, timedelta, timezone
from decimal import Decimal

_DURATION_RE = re.compile(
    r"P(?:([0-9]+)Y)?(?:([0-9]+)M)?(?:([0-9]+)W)?(?:([0-9]+)D)?"
    r"(?:T(?:([0-9]+)H)?(?:([0-9]+)M)?(?:([0-9]+(?:\.[0-9]+)?)S)?)?"
)


@dataclass(frozen=True)
class Duration:
    years: int = 0
    months: int = 0
    weeks: int = 0
    days: int = 0
    hours: int = 0
    minutes: int = 0
    seconds: float = 0


def parse(text: str) -> Duration:
    """Parse an ISO 8601 duration."""
    match = _DURATION_RE.fullmatch(text)
    if (
        not match
        or not any(match.groups())
        or ("T" in text and not any(match.groups()[4:]))
    ):
        raise ValueError(f"invalid duration: {text!r}")
    *ints, seconds = match.groups()
    years, months, weeks, days, hours, minutes = (int(n or 0) for n in ints)
    if seconds is None:
        seconds = 0
    elif "." in seconds:
        seconds = float(seconds)
    else:
        seconds = int(seconds)
    return Duration(years, months, weeks, days, hours, minutes, seconds)


def format(duration: Duration) -> str:
    """Write ``duration`` in canonical ISO 8601 form."""
    d = duration
    date_parts = ((d.years, "Y"), (d.months, "M"), (d.weeks, "W"), (d.days, "D"))
    time_parts = ((d.hours, "H"), (d.minutes, "M"), (d.seconds, "S"))
    if any(n < 0 for n, _ in date_parts + time_parts):
        raise ValueError(f"negative duration part: {duration!r}")
    text = "P" + "".join(f"{_number(n)}{u}" for n, u in date_parts if n)
    time = "".join(f"{_number(n)}{u}" for n, u in time_parts if n)
    if time:
        text += "T" + time
    return text if len(text) > 1 else "PT0S"


def _number(n: float) -> str:
    if n == int(n):
        return str(int(n))
    # Via repr, so 0.1 is "0.1" and 1e-07 is "0.0000001".
    return format(Decimal(repr(n)), "f")


def add(moment: datetime, duration: Duration) -> datetime:
    """``moment`` plus ``duration``."""
    d = duration
    total_months = moment.year * 12 + moment.month - 1 + d.years * 12 + d.months
    year, month = divmod(total_months, 12)
    month += 1
    day = min(moment.day, calendar.monthrange(year, month)[1])
    moment = moment.replace(year=year, month=month, day=day)
    elapsed = timedelta(
        weeks=d.weeks, days=d.days, hours=d.hours, minutes=d.minutes, seconds=d.seconds
    )
    if moment.tzinfo is None:
        return moment + elapsed
    # Aware arithmetic in Python is wall-clock time; go through UTC so the
    # result is exact elapsed time across offset changes.
    return (moment.astimezone(timezone.utc) + elapsed).astimezone(moment.tzinfo)

